INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('touchkiss/mindme/algolia-search', 'community', 'touchkiss', 'mindme', 'touchkiss/mindme', 'algolia-search', 0, 0, 0, '2026-02-18T01:08:43.479Z', '2026-02-18T09:38:30.505Z', NULL, '{"id":"touchkiss/mindme/algolia-search","name":"algolia-search","description":{"zh":"Algolia Search 是一个强大的搜索解决方案，提供即时搜索功能。它可以与 React 和 Next.js 集成，实现现代 Web 应用的搜索功能","ja":"Algolia Search は強力な検索ソリューションであり、インスタント検索機能を提供します。React と Next.js と統合して、モダンな Web アプリケーションの検索機能を実現します","ko":"Algolia Search는 강력한 검색 솔루션으로 즉시 검색 기능을 제공합니다. React 및 Next.js와 통합하여 현대적인 웹 애플리케이션의 검색 기능을 구현합니다","es":"La integración de búsqueda Algolia permite a los desarrolladores crear experiencias de búsqueda personalizadas y potentes en sus aplicaciones","fr":"L''intégration de recherche Algolia permet aux développeurs de créer des expériences de recherche personnalisées et puissantes dans leurs applications","de":"Die Integration der Algolia-Suche ermöglicht es Entwicklern, personalisierte und leistungsstarke Sucherfahrungen in ihren Anwendungen zu erstellen","pt":"A integração de busca Algolia permite uma experiência de busca personalizada e escalável em suas aplicações.","ru":"Интеграция поиска Algolia позволяет создать персонализированный и масштабируемый опыт поиска в ваших приложениях.","ar":"يمكّن دمج بحث Algolia من تجربة بحث مخصصة وقابلة للتطوير في تطبيقاتك.","en":"know yourself"},"seo":{"title":{"zh":"Algolia 搜索集成 - 即时搜索解决方案","ja":"Algolia 検索統合 - インスタント検索ソリューション","ko":"Algolia 검색 통합 - 즉시 검색 솔루션","es":"Integración de búsqueda Algolia","fr":"Intégration de recherche Algolia","de":"Algolia-Suche Integration","pt":"Integração de Busca Algolia","ru":"Интеграция поиска Algolia","ar":"تكامل بحث Algolia","en":"algolia-search"},"description":{"zh":"Algolia Search 是一个强大的搜索解决方案，提供即时搜索功能。它可以与 React 和 Next.js 集成，实现现代 Web 应用的搜索功能","ja":"Algolia Search は強力な検索ソリューションであり、インスタント検索機能を提供します。React と Next.js と統合して、モダンな Web アプリケーションの検索機能を実現します","ko":"Algolia Search는 강력한 검색 솔루션으로 즉시 검색 기능을 제공합니다. React 및 Next.js와 통합하여 현대적인 웹 애플리케이션의 검색 기능을 구현합니다","es":"La integración de búsqueda Algolia permite a los desarrolladores crear experiencias de búsqueda personalizadas y potentes en sus aplicaciones","fr":"L''intégration de recherche Algolia permet aux développeurs de créer des expériences de recherche personnalisées et puissantes dans leurs applications","de":"Die Integration der Algolia-Suche ermöglicht es Entwicklern, personalisierte und leistungsstarke Sucherfahrungen in ihren Anwendungen zu erstellen","pt":"A integração de busca Algolia permite uma experiência de busca personalizada e escalável em suas aplicações.","ru":"Интеграция поиска Algolia позволяет создать персонализированный и масштабируемый опыт поиска в ваших приложениях.","ar":"يمكّن دمج بحث Algolia من تجربة بحث مخصصة وقابلة للتطوير في تطبيقاتك.","en":"know yourself"},"definition":{"en":"know yourself"},"features":{"zh":["React InstantSearch 与 Hooks 集成","Next.js 服务器端集成","支持即时搜索和筛选","提供用 SearchBox、Hits、RefinementList 和 Pagination 的钩子","支持自定义 widget 组件"],"ja":["React InstantSearch と Hooks の統合","Next.js サーバーサイド統合","インスタント検索とフィルタリングのサポート","SearchBox、Hits、RefinementList、Pagination 用のフックの提供","カスタム widget コンポーネントのサポート"],"ko":["React InstantSearch 및 Hooks 통합","Next.js 서버측 통합","즉시 검색 및 필터링 지원","SearchBox, Hits, RefinementList 및 Pagination용 훅 제공","사용자 지정 widget 구성 요소 지원"],"es":["Integración con React InstantSearch","Uso de hooks para la búsqueda en tiempo real","Personalización de widgets con classnames","Soporte para Next.js Server-Side","Acceso a resultados de búsqueda y facetas","Paginación de resultados"],"fr":["Intégration avec React InstantSearch","Utilisation de hooks pour la recherche en temps réel","Personnalisation de widgets avec des classnames","Prise en charge de Next.js Server-Side","Accès aux résultats de recherche et aux facettes","Pagination des résultats"],"de":["Integration mit React InstantSearch","Verwendung von Hooks für die Echtzeit-Suche","Anpassung von Widgets mit Classnames","Unterstützung für Next.js Server-Side","Zugriff auf Suchergebnisse und Facetten","Paginierung von Ergebnissen"],"pt":["Integração com React InstantSearch","Uso de hooks para busca personalizada","Suporte a server-side rendering com Next.js","Personalização de widgets com classnames","Acesso a resultados de busca com useHits","Filtragem de facetas com useRefinementList"],"ru":["Интеграция с React InstantSearch","Использование хуков для персонализированного поиска","Поддержка серверного рендеринга с Next.js","Настройка виджетов с помощью классов","Доступ к результатам поиска с useHits","Фильтрация фрагментов с помощью useRefinementList"],"ar":["دمج مع React InstantSearch","استخدام Hooks للبحث المخصص","دعم Server-Side Rendering مع Next.js","تخصيص Widgets باستخدام Classnames","الوصول إلى نتائج البحث مع useHits","المرشحات الجزئية مع useRefinementList"]},"keywords":{"zh":["Algolia Search","即时搜索","React InstantSearch","Next.js","搜索解决方案","服务器端集成","Hooks","widget 组件"],"ja":["Algolia Search","インスタント検索","React InstantSearch","Next.js","検索ソリューション","サーバーサイド統合","Hooks","widget コンポーネント"],"ko":["Algolia Search","즉시 검색","React InstantSearch","Next.js","검색 솔루션","서버측 통합","Hooks","widget 구성 요소"],"es":["búsqueda Algolia","React InstantSearch","hooks de búsqueda","Next.js Server-Side","personalización de widgets","resultados de búsqueda","facetas de búsqueda","paginación de resultados"],"fr":["recherche Algolia","React InstantSearch","hooks de recherche","Next.js Server-Side","personnalisation de widgets","résultats de recherche","facettes de recherche","pagination des résultats"],"de":["Algolia-Suche","React InstantSearch","Hooks für die Suche","Next.js Server-Side","Anpassung von Widgets","Suchergebnisse","Facetten der Suche","Paginierung von Ergebnissen"],"pt":["algolia search","react instantsearch","next.js","busca personalizada","server-side rendering","hooks","classnames","usehits","userefinementlist"],"ru":["algolia поиск","react instantsearch","next.js","персонализированный поиск","серверный рендеринг","хуки","классы","usehits","userefinementlist"],"ar":["بحث algolia","react instantsearch","next.js","بحث مخصص","server-side rendering","hooks","classnames","usehits","userefinementlist"]}},"owner":"touchkiss","repo":"mindme","repoPath":"touchkiss/mindme","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.479Z","topics":[],"category":"community","skillMd":{"name":"algolia-search","description":"Expert patterns for Algolia search implementation, indexing strategies, React InstantSearch, and relevance tuning Use when: adding search to, algolia, instantsearch, search api, search functionality.","bodyPreview":"# Algolia Search Integration\n\n## Patterns\n\n### React InstantSearch with Hooks\n\nModern React InstantSearch setup using hooks for type-ahead search.\n\nUses react-instantsearch-hooks-web package with algoliasearch client.\nWidgets are components that can be customized with classnames.\n\nKey hooks:\n- useSearchBox: Search input handling\n- useHits: Access search results\n- useRefinementList: Facet filtering\n- usePagination: Result pagination\n- useInstantSearch: Full state access\n\n\n### Next.js Server-Side","body":"# Algolia Search Integration\n\n## Patterns\n\n### React InstantSearch with Hooks\n\nModern React InstantSearch setup using hooks for type-ahead search.\n\nUses react-instantsearch-hooks-web package with algoliasearch client.\nWidgets are components that can be customized with classnames.\n\nKey hooks:\n- useSearchBox: Search input handling\n- useHits: Access search results\n- useRefinementList: Facet filtering\n- usePagination: Result pagination\n- useInstantSearch: Full state access\n\n\n### Next.js Server-Side Rendering\n\nSSR integration for Next.js with react-instantsearch-nextjs package.\n\nUse <InstantSearchNext> instead of <InstantSearch> for SSR.\nSupports both Pages Router and App Router (experimental).\n\nKey considerations:\n- Set dynamic = ''force-dynamic'' for fresh results\n- Handle URL synchronization with routing prop\n- Use getServerState for initial state\n\n\n### Data Synchronization and Indexing\n\nIndexing strategies for keeping Algolia in sync with your data.\n\nThree main approaches:\n1. Full Reindexing - Replace entire index (expensive)\n2. Full Record Updates - Replace individual records\n3. Partial Updates - Update specific attributes only\n\nBest practices:\n- Batch records (ideal: 10MB, 1K-10K records per batch)\n- Use incremental updates when possible\n- partialUpdateObjects for attribute-only changes\n- Avoid deleteBy (computationally expensive)\n\n\n## ⚠️ Sharp Edges\n\n| Issue | Severity | Solution |\n|-------|----------|----------|\n| Issue | critical | See docs |\n| Issue | high | See docs |\n| Issue | medium | See docs |\n| Issue | medium | See docs |\n| Issue | medium | See docs |\n| Issue | medium | See docs |\n| Issue | medium | See docs |\n| Issue | medium | See docs |\n"},"lastSynced":"2026-02-18T09:38:30.505Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced search integration capabilities with Algolia","zh":"非常适合需要高级搜索集成能力的前端代理，特别是与Algolia集成","ja":"Algoliaとの高度な検索統合機能を必要とするフロントエンドエージェントに最適","ko":"Algolia와의 고급 검색 통합 기능이 필요한 프론트엔드 에이전트에게 최적","es":"Perfecto para agentes frontend que necesitan capacidades de integración de búsqueda avanzada con Algolia","fr":"Parfait pour les agents frontend nécessitant des capacités d''intégration de recherche avancée avec Algolia","de":"Perfekt für Frontend-Agents, die erweiterte Suchintegrationsfunktionen mit Algolia benötigen","pt":"Perfeito para agentes de frontend que precisam de capacidades avançadas de integração de pesquisa com a Algolia","ru":"Идеально для фронтенд-агентов, которым требуются расширенные возможности интеграции поиска с Algolia","ar":"مثالي لعميل الواجهة الأمامية الذين يحتاجون إلى إمكانيات متقدمة لدمج البحث مع Algolia"},"recommendation":{"en":"Empowers agents to integrate robust search functionality using react-instantsearch-hooks-web and algoliasearch client, enabling features like type-ahead search, facet filtering, and result pagination with useSearchBox, useHits, useRefinementList, usePagination, and useInstantSearch hooks","zh":"赋予代理集成强大的搜索功能，使用react-instantsearch-hooks-web和algoliasearch客户端，实现诸如类型前搜索、面板过滤和结果分页等功能，使用useSearchBox、useHits、useRefinementList、usePagination和useInstantSearch钩子","ja":"react-instantsearch-hooks-webとalgoliasearchクライアントを使用して、タイプアヘッド検索、ファセットフィルタリング、結果のページネーションなどの機能を実現する強力な検索機能をエージェントに統合することを可能にします。useSearchBox、useHits、useRefinementList、usePagination、useInstantSearchのフックを使用","ko":"react-instantsearch-hooks-web와 algoliasearch 클라이언트를 사용하여 강력한 검색 기능을 에이전트에 통합할 수 있도록 하여, 유형 앞 검색, 패싯 필터링 및 결과 페이지네이션과 같은 기능을 사용할 수 있습니다. useSearchBox, useHits, useRefinementList, usePagination 및 useInstantSearch 훅을 사용","es":"Habilita a los agentes a integrar una funcionalidad de búsqueda robusta utilizando react-instantsearch-hooks-web y el cliente algoliasearch, lo que permite características como búsqueda de tipo adelantado, filtrado de facetas y paginación de resultados con los hooks useSearchBox, useHits, useRefinementList, usePagination y useInstantSearch","fr":"Permet aux agents d''intégrer une fonctionnalité de recherche robuste en utilisant react-instantsearch-hooks-web et le client algoliasearch, ce qui permet des fonctionnalités telles que la recherche de type avant, le filtrage de facettes et la pagination des résultats avec les hooks useSearchBox, useHits, useRefinementList, usePagination et useInstantSearch","de":"Ermöglicht es Agents, eine robuste Suchfunktion mit react-instantsearch-hooks-web und dem algoliasearch-Client zu integrieren, wodurch Funktionen wie Vorwärts-Tippen-Suche, Facettensuche und Ergebnisseite mit den Hooks useSearchBox, useHits, useRefinementList, usePagination und useInstantSearch ermöglicht werden","pt":"Habilita os agentes a integrar funcionalidades de pesquisa robustas usando react-instantsearch-hooks-web e cliente algoliasearch, permitindo recursos como pesquisa de preenchimento automático, filtragem de facetas e paginação de resultados com useSearchBox, useHits, useRefinementList, usePagination e useInstantSearch hooks","ru":"Наделяет агентов возможностью интегрировать функции расширенного поиска с помощью react-instantsearch-hooks-web и клиента algoliasearch, что позволяет использовать функции такие как поиск с автоматическим дополнением, фильтрация по фрагментам и постраничный вывод результатов с помощью хуков useSearchBox, useHits, useRefinementList, usePagination и useInstantSearch","ar":"يُمكن العميل من دمج وظائف بحث قوية باستخدام react-instantsearch-hooks-web وعميل algoliasearch، مما يتيح ميزات مثل بحث التكميل التلقائي وتصفية الفروع وتنقّل النتائج باستخدام hooks useSearchBox وuseHits وuseRefinementList وusePagination وuseInstantSearch"},"useCases":{"en":["Implementing type-ahead search with react-instantsearch-hooks-web","Customizing search result layouts with useRefinementList and useHits","Optimizing search performance with usePagination and useInstantSearch"],"zh":["使用react-instantsearch-hooks-web实现类型前搜索","使用useRefinementList和useHits自定义搜索结果布局","使用usePagination和useInstantSearch优化搜索性能"],"ja":["react-instantsearch-hooks-webを使用したタイプアヘッド検索の実装","useRefinementListとuseHitsを使用した検索結果レイアウトのカスタマイズ","usePaginationとuseInstantSearchを使用した検索パフォーマンスの最適化"],"ko":["react-instantsearch-hooks-web를 사용한 유형 앞 검색 구현","useRefinementList와 useHits를 사용한 검색 결과 레이아웃 사용자 정의","usePagination과 useInstantSearch를 사용한 검색 성능 최적화"],"es":["Implementar la búsqueda de tipo adelantado con react-instantsearch-hooks-web","Personalizar los diseños de los resultados de la búsqueda con useRefinementList y useHits","Optimizar el rendimiento de la búsqueda con usePagination y useInstantSearch"],"fr":["Mettre en œuvre la recherche de type avant avec react-instantsearch-hooks-web","Personnaliser les mises en page des résultats de recherche avec useRefinementList et useHits","Optimiser les performances de recherche avec usePagination et useInstantSearch"],"de":["Implementierung der Vorwärts-Tippen-Suche mit react-instantsearch-hooks-web","Anpassen der Suchergebnislayouts mit useRefinementList und useHits","Optimierung der Suchleistung mit usePagination und useInstantSearch"],"pt":["Implementação de pesquisa de preenchimento automático com react-instantsearch-hooks-web","Personalização de layouts de resultados de pesquisa com useRefinementList e useHits","Otimização do desempenho de pesquisa com usePagination e useInstantSearch"],"ru":["Реализация поиска с автоматическим дополнением с помощью react-instantsearch-hooks-web","Настройка макетов результатов поиска с помощью useRefinementList и useHits","Оптимизация производительности поиска с помощью usePagination и useInstantSearch"],"ar":["تنفيذ بحث التكميل التلقائي باستخدام react-instantsearch-hooks-web","تخصيص تخطيطات نتائج البحث باستخدام useRefinementList وuseHits","تحسين أداء البحث باستخدام usePagination وuseInstantSearch"]},"limitations":{"en":["Requires Algolia account and index setup","Limited to React and Next.js frameworks"],"zh":["需要Algolia账户和索引设置","仅限于React和Next.js框架"],"ja":["Algoliaアカウントとインデックスの設定が必要","ReactとNext.jsのフレームワークのみに限定"],"ko":["Algolia 계정 및 인덱스 설정이 필요","React 및 Next.js 프레임워크만 해당"],"es":["Requiere una cuenta y configuración de índice de Algolia","Limitado a los frameworks React y Next.js"],"fr":["Nécessite un compte et une configuration d''index Algolia","Limité aux frameworks React et Next.js"],"de":["Erfordert ein Konto und eine Indexeinstellung von Algolia","Begrenzt auf die Frameworks React und Next.js"],"pt":["Exige conta e configuração de índice da Algolia","Limitado aos frameworks React e Next.js"],"ru":["Требует учетной записи и настройки индекса Algolia","Ограничен фреймворками React и Next.js"],"ar":["يتطلب حسابًا وإعداد فهرس Algolia","محدود بإطارات العمل React وNext.js"]},"version":3},"qualityScore":0}');
