INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vuthuonghai-steve/KLTN/server-sent-events', 'community', 'vuthuonghai-steve', 'KLTN', 'vuthuonghai-steve/KLTN', 'server-sent-events', 0, 0, 55, '2026-02-18T01:08:43.487Z', '2026-02-18T10:15:58.519Z', NULL, '{"id":"vuthuonghai-steve/KLTN/server-sent-events","name":"server-sent-events","description":{"zh":"Server-Sent Events (SSE) 是一种实时服务器推送技术，适用于进度更新、通知和实时数据feed","ja":"Server-Sent Events (SSE) はリアルタイムサーバー推送技術であり、進度更新、通知、リアルタイムデータfeedに適している","ko":"서버 센트 이벤트 (SSE) 는 실시간 서버 푸시 기술로 진행 업데이트, 알림 및 실시간 데이터 피드에 적합","es":"Los Eventos Enviados por Servidor (SSE) permiten la transmisión en tiempo real de actualizaciones de progreso y notificaciones desde el servidor al cliente","fr":"Les Événements Envoyés par Serveur (SSE) permettent la diffusion en temps réel de mises à jour de progrès et de notifications depuis le serveur vers le client","de":"Server-Sent Events (SSE) ermöglichen das Echtzeit-Streaming von Fortschrittsupdates und Benachrichtigungen vom Server zum Client","pt":"Server-Sent Events é uma tecnologia para transmissão em tempo real de dados do servidor para o cliente. Ela é ideal para atualizações de progresso, notificações e feeds de dados ao vivo.","ru":"Серверные События - это технология для потоковой передачи данных с сервера на клиент в реальном времени. Она идеальна для обновлений прогресса, уведомлений и прямых данных.","ar":"أحداث الملقم هي تقنية للبث المباشر في الوقت الحقيقي للبيانات من الملقم إلى العميل. وهي مثالية لتحديثات التقدم، والإشعارات، وتغذية البيانات الحية","en":""},"seo":{"title":{"zh":"Server-Sent Events (SSE) 实时服务器推送","ja":"Server-Sent Events (SSE) のリアルタイムサーバー推送","ko":"서버 센트 이벤트 (SSE) 실시간 서버 푸시","es":"Eventos Enviados por Servidor (SSE) - Transmisión en Tiem...","fr":"Événements Envoyés par Serveur (SSE) - Diffusion en Temps...","de":"Server-Sent Events (SSE) - Echtzeit-Streaming","