INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macho715/tr_dashboard/agi-schedule-shift', 'community', 'macho715', 'tr_dashboard', 'macho715/tr_dashboard', 'agi-schedule-shift', 0, 0, 55, '2026-02-18T01:08:43.488Z', '2026-02-18T10:20:47.859Z', NULL, '{"id":"macho715/tr_dashboard/agi-schedule-shift","name":"agi-schedule-shift","description":{"zh":"AGI 日程.shift 技术是用于自动化日程调整的解决方案，适用于开发者","ja":"AGI スケジュールシフトは、スケジュールを自動的に調整する技術です","ko":"AGI 일정 시프트는 자동 일정을 조정하는 데 사용되는 기술입니다","es":"El skill ''agi-schedule-shift'' permite desplazar la programación AGI de forma automática. Se ejecuta cuando se proporcionan fechas pivot y nuevas","fr":"Le skill ''agi-schedule-shift'' permet de décaler l''horaire AGI de manière automatique. Il s''exécute lorsque les dates pivot et nouvelles sont fournies","de":"Der Skill ''agi-schedule-shift'' ermöglicht es, den AGI-Zeitplan automatisch zu verschieben. Er wird ausgeführt, wenn Pivot- und neue Daten bereitgestellt werden","pt":"O agi-schedule-shift é uma habilidade de agendamento de turnos que executa o pipeline de atualização diária e verifica a integridade do pipeline. Ela é executada quando uma nova data é fornecida","ru":"AGI Сменный график - это навык, который выполняет ежедневную aktualizацию конвейера и проверяет его целостность. Он запускается, когда предоставлена новая дата","ar":"جدولةAGI هي مهارة جدولة تنفذ تحديث يومي للخط الأنابيب وتتحقق من صلاحيته. يتم تشغيلها عند توفير تاريخ جديد","en":""},"seo":{"title":{"zh":"AGI 日程.shift 技术","ja":"AGI スケジュールシフト","ko":"AGI 일정 시프트","es":"Desplazar programación AGI","fr":"Décaler l''horaire AGI","de":"AGI-Zeitplan verschieben","pt":"Agendamento de Turnos AGI - Desenvolvedores","ru":"AGI Сменный график - Разработчики","ar":"جدولةAGI - مبرمجو","en":"agi-schedule-shift"},"description":{"zh":"AGI 日程.shift 技术是用于自动化日程调整的解决方案，适用于开发者","ja":"AGI スケジュールシフトは、スケジュールを自動的に調整する技術です","ko":"AGI 일정 시프트는 자동 일정을 조정하는 데 사용되는 기술입니다","es":"El skill ''agi-schedule-shift'' permite desplazar la programación AGI de forma automática. Se ejecuta cuando se proporcionan fechas pivot y nuevas","fr":"Le skill ''agi-schedule-shift'' permet de décaler l''horaire AGI de manière automatique. Il s''exécute lorsque les dates pivot et nouvelles sont fournies","de":"Der Skill ''agi-schedule-shift'' ermöglicht es, den AGI-Zeitplan automatisch zu verschieben. Er wird ausgeführt, wenn Pivot- und neue Daten bereitgestellt werden","pt":"O agi-schedule-shift é uma habilidade de agendamento de turnos que executa o pipeline de atualização diária e verifica a integridade do pipeline. Ela é execu...","ru":"AGI Сменный график - это навык, который выполняет ежедневную aktualizацию конвейера и проверяет его целостность. Он запускается, когда предоставлена новая дата","ar":"جدولةAGI هي مهارة جدولة تنفذ تحديث يومي للخط الأنابيب وتتحقق من صلاحيته. يتم تشغيلها عند توفير تاريخ جديد","en":""},"definition":{"en":""},"features":{"zh":["自动化日程调整","支持 JSON 和 HTML 格式","可自定义调度规则","适用于开发者"],"ja":["自動スケジュール調整","JSON と HTML 形式をサポート","カスタム可能なスケジュールルール","開発者向け"],"ko":["자동 일정을 조정","JSON 및 HTML 형식 지원","사용자 정의 가능한 일정 규칙","개발자를 위한"],"es":["Automatización de la modificación del horario","Ejecución condicional basada en fechas","Trabajo con archivos JSON y HTML","Compatibilidad con pipeline integrado","Soporte para varios idiomas"],"fr":["Automatisation de la modification de l''horaire","Exécution conditionnelle basée sur les dates","Travail avec des fichiers JSON et HTML","Compatibilité avec pipeline intégré","Prise en charge de plusieurs langues"],"de":["Automatisierung der Änderung des Zeitplans","Bedingte Ausführung basierend auf Daten","Arbeit mit JSON- und HTML-Dateien","Kompatibilität mit integriertem Pipeline","Unterstützung für mehrere Sprachen"],"pt":["Executa o pipeline de atualização diária","Verifica a integridade do pipeline","Aceita datas de início e fim","Trabalha apenas com arquivos JSON e HTML","Executa em um diretório específico"],"ru":["Выполняет ежедневную aktualizацию конвейера","Проверяет целостность конвейера","Принимает даты начала и окончания","Работает только с файлами JSON и HTML","Выполняется в конкретном каталоге"],"ar":["تنفذ تحديث يومي للخط الأنابيب","تتحقق من صلاحيته","تقبل تواريخ البداية والنهاية","تعمل فقط مع ملفات JSON و HTML","تشتغل في دليل معين"]},"keywords":{"zh":["AGI 日程.shift","自动化日程调整","开发者工具","JSON 格式","HTML 格式","调度规则"],"ja":["AGI スケジュールシフト","自動スケジュール調整","開発者ツール","JSON 形式","HTML 形式","スケジュールルール"],"ko":["AGI 일정 시프트","자동 일정을 조정","개발자 도구","JSON 형식","HTML 형식","일정 규칙"],"es":["desplazar programación AGI","automatizar horario","skill de programación","pipeline integrado","JSON y HTML","fechas pivot","nuevas fechas","modificación automática"],"fr":["décaler l''horaire AGI","automatiser l''horaire","skill de programmation","pipeline intégré","JSON et HTML","dates pivot","nouvelles dates","modification automatique"],"de":["AGI-Zeitplan verschieben","Zeitplan automatisieren","Skill für die Programmierung","integrierter Pipeline","JSON und HTML","Pivot-Daten","neue Daten","automatische Änderung"],"pt":["agi-schedule-shift","agendamento de turnos","pipeline de atualização diária","verificação de integridade","desenvolvedores","programação"],"ru":["AGI Сменный график","сменный график","ежедневная aktualizация конвейера","проверка целостности","разработчики","программирование"],"ar":["جدولةAGI","جدولة","تحديث يومي للخط الأنابيب","تحقق من الصلاحي","مطورون","برمجة"]}},"owner":"macho715","repo":"tr_dashboard","repoPath":"macho715/tr_dashboard","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.488Z","topics":[],"category":"community","skillMd":{"name":"agi-schedule-shift","description":"Shifts AGI TR schedule (JSON/HTML) by delta days after pivot date. Use when delaying schedule, 일정 시프트, schedule shift, pivot_date and new_date provided. Part of integrated pipeline step 1.","bodyPreview":"# agi-schedule-shift\n\n## Pipeline Position\n\n- **Step 1** of the integrated pipeline: **1) agi-schedule-shift** → 2) agi-schedule-daily-update → 3) agi-schedule-pipeline-check → 4) weather-go-nogo.\n- Run when pivot_date·new_date provided; otherwise confirm \"no shift\".\n\n## Scope\n\n- All work in `files/` only. JSON and HTML read/write only within `files/`.\n\n## When to Use\n\n- \"일정 시프트\", \"schedule shift\", \"일정 2일 연기\", \"AGI schedule delay\", \"전체 일정 자동 수정\"\n\n## Inputs\n\n| Item | Description | Example |\n|----","body":"# agi-schedule-shift\n\n## Pipeline Position\n\n- **Step 1** of the integrated pipeline: **1) agi-schedule-shift** → 2) agi-schedule-daily-update → 3) agi-schedule-pipeline-check → 4) weather-go-nogo.\n- Run when pivot_date·new_date provided; otherwise confirm \"no shift\".\n\n## Scope\n\n- All work in `files/` only. JSON and HTML read/write only within `files/`.\n\n## When to Use\n\n- \"일정 시프트\", \"schedule shift\", \"일정 2일 연기\", \"AGI schedule delay\", \"전체 일정 자동 수정\"\n\n## Inputs\n\n| Item | Description | Example |\n|------|-------------|---------|\n| pivot_date | Anchor date (shift only dates ≥ this) | 2026-02-01 |\n| new_date | Target date for pivot | 2026-02-03 |\n| delta_days | new_date − pivot_date | +2 |\n\n## Procedure\n\n### 1) JSON Shift\n\n- `files/agi tr final schedule.json` → `activities[].planned_start`, `planned_finish`.\n- Apply +delta_days only to dates ≥ pivot_date.\n- Keep `duration` unchanged.\n- Update `summary.date_range` if applicable.\n\n### 2) HTML Shift\n\n- `projectStart`, `projectEnd`, `ganttData` rows, voyage-card `data-start`/`data-end`.\n- Apply same delta to dates ≥ pivot_date.\n- Format: `YYYY-MM-DD`.\n\n### 3) Script\n\n- **Path**: `files/schedule_shift.py`\n- **Run**: From `files/`, `python schedule_shift.py [--dry-run] [--backup]`\n- Set `PIVOT`, `DELTA_DAYS` in script before run.\n\n## Validation\n\n- All `planned_start` ≤ `planned_finish`.\n- Activity order preserved.\n\n## Safety\n\n- No reads/writes outside `files/`.\n- Do not shift dates before pivot_date.\n- Shift JSON and HTML together for consistency.\n\n## After Shift\n\n- Run **agi-schedule-pipeline-check** (step 3) so Voyage Cards, tide-table, ganttData stay in sync.\n\n## Output Format\n\n- Follow `agentskillguide/DASHBOARD_OUTPUT_SCHEMA.md`.\n"},"lastSynced":"2026-02-18T10:20:47.859Z","agentAnalysis":{"suitability":{"en":"Ideal for Schedule Management Agents requiring automated pipeline adjustments and JSON/HTML file handling","zh":"适用于需要自动管道调整和JSON/HTML文件处理的计划管理代理","ja":"自動パイプライン調整およびJSON/HTMLファイルハンドリングを必要とするスケジュール管理エージェントに適している","ko":"자동 파이프라인 조정 및 JSON/HTML 파일 처리가 필요한 스케줄 관리 에이전트에 적합","es":"Ideal para Agentes de Gestión de Programación que requieren ajustes de canalización automatizados y manipulación de archivos JSON/HTML","fr":"Idéal pour les Agents de Gestion de Planning nécessitant des ajustements de pipeline automatisés et une manipulation de fichiers JSON/HTML","de":"Ideal für Schedule-Management-Agents, die automatisierte Pipeline-Anpassungen und JSON/HTML-Dateihandling erfordern","pt":"Ideal para Agentes de Gerenciamento de Agendamento que exigem ajustes automatizados de pipeline e manipulação de arquivos JSON/HTML","ru":"Идеально подходит для агентов управления расписанием, требующих автоматических корректировок конвейера и обработки файлов JSON/HTML","ar":"مثالي لعمليات إدارة الجدول التي تتطلب تعديلات خط أنابيب آلية ومعالجة ملفات JSON/HTML"},"recommendation":{"en":"Empowers agents to shift schedules programmatically, leveraging pipeline positions and file read/write capabilities within the `files/` directory, specifically handling JSON and HTML formats, and enabling seamless integration with subsequent pipeline steps like `agi-schedule-daily-update` and `agi-schedule-pipeline-check`","zh":"赋予代理程序以编程方式调整时间表的能力，利用管道位置和文件读/写能力在`files/`目录内，特别处理JSON和HTML格式，并实现与后续管道步骤（如`agi-schedule-daily-update`和`agi-schedule-pipeline-check`）的无缝集成","ja":"エージェントにスケジュールをプログラム的にシフトさせる能力を付与し、パイプライン内の位置と`files/`ディレクトリ内のファイルの読み/書き能力を活用し、特にJSONとHTML形式を処理し、`agi-schedule-daily-update`および`agi-schedule-pipeline-check`などの後のパイプラインステップとのシームレスな統合を可能にしている","ko":"에이전트가 프로그래밍 방식으로 스케줄을 조정할 수 있는 능력을 부여하며, 파이프라인 위치와 `files/` 디렉토리 내의 파일 읽기/쓰기 기능을 활용하여, 특히 JSON 및 HTML 형식을 처리하고, `agi-schedule-daily-update` 및 `agi-schedule-pipeline-check`와 같은 후속 파이프라인 단계와의无缝 통합을 가능하게 함","es":"Habilita a los agentes a cambiar los horarios de forma programática, aprovechando las posiciones de la canalización y las capacidades de lectura/escritura de archivos dentro del directorio `files/`, específicamente para manejar formatos JSON y HTML, y permitiendo una integración sin problemas con pasos de canalización posteriores como `agi-schedule-daily-update` y `agi-schedule-pipeline-check`","fr":"Permet aux agents de déplacer les horaires de manière programmatique, en exploitant les positions de pipeline et les capacités de lecture/écriture de fichiers dans le répertoire `files/`, en gérant spécifiquement les formats JSON et HTML, et en permettant une intégration transparente avec les étapes de pipeline suivantes comme `agi-schedule-daily-update` et `agi-schedule-pipeline-check`","de":"Ermächtigt Agents, Termine programmgesteuert zu ändern, indem Pipeline-Positionen und Dateilese-/Schreibfunktionen innerhalb des Verzeichnisses `files/` genutzt werden, insbesondere zur Handhabung von JSON- und HTML-Formaten, und ermöglicht eine nahtlose Integration mit nachfolgenden Pipeline-Schritten wie `agi-schedule-daily-update` und `agi-schedule-pipeline-check`","pt":"Habilita os agentes a alterar os horários programaticamente, aproveitando as posições do pipeline e as capacidades de leitura/escrita de arquivos dentro do diretório `files/`, manipulando especificamente os formatos JSON e HTML, e permitindo uma integração perfeita com etapas subsequentes do pipeline, como `agi-schedule-daily-update` e `agi-schedule-pipeline-check`","ru":"Позволяет агентам изменять расписание программно, используя позиции конвейера и возможности чтения/записи файлов в директории `files/`, в частности, обрабатывая форматы JSON и HTML, и обеспечивая бесшовную интеграцию с последующими шагами конвейера, такими как `agi-schedule-daily-update` и `agi-schedule-pipeline-check`","ar":"تمكّن الوكلاء من تغيير الجدول برمجيًا، مستفيدًا من مواقف PIPELINE وقدرات قراءة/كتابة الملفات داخل الدليل `files/`، ومعاملته بشكل خاص لتنسيقات JSON و HTML، وتمكين التكامل السلس مع خطوات PIPELINE اللاحقة مثل `agi-schedule-daily-update` و `agi-schedule-pipeline-check`"},"useCases":{"en":["Automating schedule shifts based on pivot dates and new dates","Updating JSON and HTML files within the `files/` directory to reflect schedule changes","Integrating with weather-based decision pipelines like `weather-go-nogo`"],"zh":["基于枢轴日期和新日期自动调整时间表","在`files/`目录中更新JSON和HTML文件以反映时间表更改","与天气决策管道（如`weather-go-nogo`）集成"],"ja":["枢軸日と新しい日付に基づいてスケジュールを自動的にシフトする","`files/`ディレクトリ内のJSONとHTMLファイルを更新してスケジュールの変更を反映する","天候に基づく意思決定パイプライン（例：`weather-go-nogo`）との統合"],"ko":["잠재 날짜와 신규 날짜를 기준으로 자동으로 스케줄을 조정","`files/` 디렉토리 내의 JSON 및 HTML 파일을 업데이트하여 스케줄 변경을 반영","날씨 기반 의사 결정 파이프라인 (`weather-go-nogo` 등)과 통합"],"es":["Automatizar cambios de horario en función de fechas de pivote y nuevas fechas","Actualizar archivos JSON y HTML dentro del directorio `files/` para reflejar cambios en el horario","Integrarse con canalizaciones de toma de decisiones basadas en el clima como `weather-go-nogo`"],"fr":["Automatiser les changements d''horaire en fonction de dates de pivot et de nouvelles dates","Mettre à jour les fichiers JSON et HTML dans le répertoire `files/` pour refléter les changements d''horaire","S''intégrer avec des pipelines de prise de décision basés sur les conditions météorologiques comme `weather-go-nogo`"],"de":["Automatisieren von Terminverschiebungen basierend auf Pivot-Daten und neuen Daten","Aktualisieren von JSON- und HTML-Dateien innerhalb des Verzeichnisses `files/`, um Terminänderungen widerzuspiegeln","Integrieren mit wetterbasierten Entscheidungspipelines wie `weather-go-nogo`"],"pt":["Automatizar mudanças de horário com base em datas de pivot e novas datas","Atualizar arquivos JSON e HTML dentro do diretório `files/` para refletir as alterações no horário","Integrar com pipelines de tomada de decisão baseada no clima, como `weather-go-nogo`"],"ru":["Автоматизировать смену расписания на основе дат-пивотов и новых дат","Обновлять файлы JSON и HTML внутри директории `files/`, чтобы отразить изменения в расписании","Интегрироваться с конвейерами принятия решений на основе погоды, такими как `weather-go-nogo`"],"ar":["تأتمتة تغيير الجدول على أساس تواريخ المحور وتواريخ جديدة","تحديث ملفات JSON و HTML داخل الدليل `files/` لتعكس التغييرات في الجدول","التكامل مع خطوط أنابيب اتخاذ القرارات القائمة على الطقس مثل `weather-go-nogo`"]},"limitations":{"en":["Requires `pivot_date` and `new_date` inputs to function","Limited to file operations within the `files/` directory","Only supports JSON and HTML file read/write operations"],"zh":["需要`pivot_date`和`new_date`输入才能运行","仅限于`files/`目录内的文件操作","仅支持JSON和HTML文件读/写操作"],"ja":["動作するために`pivot_date`と`new_date`の入力が必要","ファイル操作は`files/`ディレクトリ内のみ","JSONとHTMLファイルの読み/書き操作のみをサポート"],"ko":["실행하기 위해 `pivot_date` 및 `new_date` 입력이 필요","`files/` 디렉토리 내의 파일 작업만 제한","JSON 및 HTML 파일 읽기/쓰기 작업만 지원"],"es":["Requiere entradas `pivot_date` y `new_date` para funcionar","Limitado a operaciones de archivos dentro del directorio `files/`","Solo admite operaciones de lectura/escritura de archivos JSON y HTML"],"fr":["Nécessite des entrées `pivot_date` et `new_date` pour fonctionner","Limité aux opérations de fichiers dans le répertoire `files/`","Ne prend en charge que les opérations de lecture/écriture de fichiers JSON et HTML"],"de":["Benötigt `pivot_date`- und `new_date`-Eingaben, um zu funktionieren","Begrenzt auf Dateioperationen innerhalb des Verzeichnisses `files/`","Unterstützt nur JSON- und HTML-Dateilese-/Schreiboperationen"],"pt":["Exige entradas `pivot_date` e `new_date` para funcionar","Limitado a operações de arquivo dentro do diretório `files/`","Apenas suporta operações de leitura/escrita de arquivos JSON e HTML"],"ru":["Требует ввода `pivot_date` и `new_date` для работы","Ограничен операциями с файлами внутри директории `files/`","Поддерживает только операции чтения/записи файлов JSON и HTML"],"ar":["يتطلب إدخال `pivot_date` و `new_date` للعمل","محدود بعمليات الملفات داخل الدليل `files/`","يدعم فقط عمليات قراءة/كتابة الملفات JSON و HTML"]},"version":3},"qualityScore":55}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pakomercado0517/tresa-contaflow-web/shadcn-ui', 'community', 'pakomercado0517', 'tresa-contaflow-web', 'pakomercado0517/tresa-contaflow-web', 'shadcn-ui', 0, 0, 70, '2026-02-18T01:08:43.487Z', '2026-02-18T10:20:25.615Z', NULL, '{"id":"pakomercado0517/tresa-contaflow-web/shadcn-ui","name":"shadcn-ui","description":{"zh":"shadcn-ui","ja":"shadcn-ui","ko":"shadcn-ui","es":"Guía para crear componentes UI accesibles y personalizables con shadcn-ui. Incluye configuración de proyectos y componentes básicos.","fr":"Guide pour créer des composants UI accessibles et personnalisables avec shadcn-ui. Inclut la configuration de projets et les composants de base.","de":"Anleitung zum Erstellen von zugänglichen und anpassbaren UI-Komponenten mit shadcn-ui. Enthält Projekt-Konfiguration und Kernkomponenten.","pt":"Guia de componentes UI shadcn-ui para desenvolvedores, com dicas de como criar componentes personalizáveis e acessíveis","ru":"Руководство по компонентам shadcn-ui для разработчиков, с советами по созданию настраиваемых и доступных компонентов","ar":"دليل مكونات شادسن-يو آي للمطورين، مع نصائح حول كيفية إنشاء مكونات مخصصة وقابلة للوصول","en":""},"seo":{"title":{"zh":"shadcn-ui","ja":"shadcn-ui","ko":"shadcn-ui","es":"Patrones de componentes UI con shadcn-ui","fr":"Modèles de composants UI avec shadcn-ui","de":"UI-Komponenten-Muster mit shadcn-ui","pt":"Guia de Componentes UI shadcn-ui","ru":"Руководство по компонентам shadcn-ui","ar":"دليل مكونات شادسن-يو آي","en":"shadcn-ui"},"description":{"zh":"shadcn-ui","ja":"shadcn-ui","ko":"shadcn-ui","es":"Guía para crear componentes UI accesibles y personalizables con shadcn-ui. Incluye configuración de proyectos y componentes básicos.","fr":"Guide pour créer des composants UI accessibles et personnalisables avec shadcn-ui. Inclut la configuration de projets et les composants de base.","de":"Anleitung zum Erstellen von zugänglichen und anpassbaren UI-Komponenten mit shadcn-ui. Enthält Projekt-Konfiguration und Kernkomponenten.","pt":"Guia de componentes UI shadcn-ui para desenvolvedores, com dicas de como criar componentes personalizáveis e acessíveis","ru":"Руководство по компонентам shadcn-ui для разработчиков, с советами по созданию настраиваемых и доступных компонентов","ar":"دليل مكونات شادسن-يو آي للمطورين، مع نصائح حول كيفية إنشاء مكونات مخصصة وقابلة للوصول","en":""},"definition":{"en":""},"features":{"zh":["shadcn-ui","Radix UI","Tailwind CSS","shadcn-ui","shadcn-ui","shadcn-ui"],"ja":["shadcn-ui","Radix UI","Tailwind CSS","shadcn-ui","shadcn-ui","shadcn-ui"],"ko":["shadcn-ui","Radix UI","Tailwind CSS","shadcn-ui","shadcn-ui","shadcn-ui"],"es":["Creación de componentes UI personalizables","Compatibilidad con Radix UI y Tailwind CSS","Guía para la configuración de proyectos","Componentes básicos como botones y formularios","Validación de formularios","Diseño accesible"],"fr":["Création de composants UI personnalisables","Compatibilité avec Radix UI et Tailwind CSS","Guide pour la configuration de projets","Composants de base tels que les boutons et les formulaires","Validation des formulaires","Conception accessible"],"de":["Erstellung von anpassbaren UI-Komponenten","Kompatibilität mit Radix UI und Tailwind CSS","Anleitung zur Projekt-Konfiguration","Kernkomponenten wie Schaltflächen und Formulare","Formular-Validierung","Zugängliches Design"],"pt":["Componentes UI personalizáveis","Acessibilidade em componentes","Integração com Radix UI e Tailwind CSS","Guia de início rápido","Configuração de projeto"],"ru":["Настройные компоненты UI","Доступность компонентов","Интеграция с Radix UI и Tailwind CSS","Быстрый старт","Настройка проекта"],"ar":["مكونات واجهة المستخدم المخصصة","إمكانية الوصول إلى المكونات","التكامل مع راديكس يو آي وتايلويند سي أس","دليل البداية السريعة","تكوين المشروع"]},"keywords":{"zh":["shadcn-ui","UI","Radix UI","Tailwind CSS","shadcn-ui","shadcn-ui"],"ja":["shadcn-ui","UI","Radix UI","Tailwind CSS","shadcn-ui","shadcn-ui"],"ko":["shadcn-ui","UI","Radix UI","Tailwind CSS","shadcn-ui","shadcn-ui"],"es":["shadcn-ui","componentes UI","Radix UI","Tailwind CSS","desarrollo web","accesibilidad web","diseño de interfaz de usuario"],"fr":["shadcn-ui","composants UI","Radix UI","Tailwind CSS","développement web","accessibilité web","conception d''interface utilisateur"],"de":["shadcn-ui","UI-Komponenten","Radix UI","Tailwind CSS","Webentwicklung","Web-Zugänglichkeit","Benutzeroberflächen-Design"],"pt":["shadcn-ui","componentes UI","acessibilidade","personalização","Radix UI","Tailwind CSS","desenvolvimento web"],"ru":["shadcn-ui","компоненты UI","доступность","настраиваемость","Radix UI","Tailwind CSS","веб-разработка"],"ar":["شادسن-يو آي","مكونات واجهة المستخدم","إمكانية الوصول","التنصيب","راديكس يو آي","تايلويند سي أس","تطوير الويب"]}},"owner":"pakomercado0517","repo":"tresa-contaflow-web","repoPath":"pakomercado0517/tresa-contaflow-web","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.487Z","topics":[],"category":"community","skillMd":{"name":"shadcn-ui","description":"Complete shadcn/ui component library guide including installation, configuration, and implementation of accessible React components. Use when setting up shadcn/ui, installing components, building forms with React Hook Form and Zod, customizing themes with Tailwind CSS, or implementing UI patterns like buttons, dialogs, dropdowns, tables, and complex form layouts.","bodyPreview":"# shadcn/ui Component Patterns\n\nExpert guide for building accessible, customizable UI components with shadcn/ui, Radix UI, and Tailwind CSS.\n\n## Table of Contents\n\n- [When to Use](#when-to-use)\n- [Quick Start](#quick-start)\n- [Installation & Setup](#installation--setup)\n- [Project Configuration](#project-configuration)\n- [Core Components](#core-components)\n  - [Button](#button-component)\n  - [Input & Form Fields](#input--form-fields)\n  - [Forms with Validation](#forms-with-validation)\n  - [Card]","body":"# shadcn/ui Component Patterns\n\nExpert guide for building accessible, customizable UI components with shadcn/ui, Radix UI, and Tailwind CSS.\n\n## Table of Contents\n\n- [When to Use](#when-to-use)\n- [Quick Start](#quick-start)\n- [Installation & Setup](#installation--setup)\n- [Project Configuration](#project-configuration)\n- [Core Components](#core-components)\n  - [Button](#button-component)\n  - [Input & Form Fields](#input--form-fields)\n  - [Forms with Validation](#forms-with-validation)\n  - [Card](#card-component)\n  - [Dialog (Modal)](#dialog-modal-component)\n  - [Select (Dropdown)](#select-dropdown-component)\n  - [Sheet (Slide-over)](#sheet-slide-over-component)\n  - [Menubar & Navigation](#menubar--navigation)\n  - [Table](#table-component)\n  - [Toast Notifications](#toast-notifications)\n- [Advanced Patterns](#advanced-patterns)\n- [Customization](#customization)\n- [Next.js Integration](#nextjs-integration)\n- [Best Practices](#best-practices)\n- [Common Component Combinations](#common-component-combinations)\n\n## When to Use\n\n- Setting up a new project with shadcn/ui\n- Installing or configuring individual components\n- Building forms with React Hook Form and Zod validation\n- Creating accessible UI components (buttons, dialogs, dropdowns, sheets)\n- Customizing component styling with Tailwind CSS\n- Implementing design systems with shadcn/ui\n- Building Next.js applications with TypeScript\n- Creating complex layouts and data displays\n\n## Quick Start\n\nFor new projects, use the automated setup:\n\n```bash\n# Create Next.js project with shadcn/ui\nnpx create-next-app@latest my-app --typescript --tailwind --eslint --app\ncd my-app\nnpx shadcn@latest init\n\n# Install essential components\nnpx shadcn@latest add button input form card dialog select\n```\n\nFor existing projects:\n\n```bash\n# Install dependencies\nnpm install tailwindcss-animate class-variance-authority clsx tailwind-merge lucide-react\n\n# Initialize shadcn/ui\nnpx shadcn@latest init\n```\n\n## What is shadcn/ui?\n\nshadcn/ui is **not** a traditional component library or npm package. Instead:\n\n- It''s a **collection of reusable components** that you can copy into your project\n- Components are **yours to customize** - you own the code\n- Built with **Radix UI** primitives for accessibility\n- Styled with **Tailwind CSS** utilities\n- Includes CLI tool for easy component installation\n\n## Installation & Setup\n\n### Initial Setup\n\n```bash\n# Initialize shadcn/ui in your project\nnpx shadcn@latest init\n```\n\nDuring setup, you''ll configure:\n- TypeScript or JavaScript\n- Style (Default, New York, etc.)\n- Base color theme\n- CSS variables or Tailwind CSS classes\n- Component installation path\n\n### Installing Individual Components\n\n```bash\n# Install a single component\nnpx shadcn@latest add button\n\n# Install multiple components\nnpx shadcn@latest add button input form\n\n# Install all components\nnpx shadcn@latest add --all\n```\n\n### Manual Installation\n\nIf you prefer manual setup:\n\n```bash\n# Install dependencies for a specific component\nnpm install @radix-ui/react-slot\n\n# Copy component code from ui.shadcn.com\n# Place in src/components/ui/\n```\n\n## Project Configuration\n\n### Required Dependencies\n\n```json\n{\n  \"dependencies\": {\n    \"@radix-ui/react-accordion\": \"^1.1.2\",\n    \"@radix-ui/react-alert-dialog\": \"^1.0.5\",\n    \"@radix-ui/react-dialog\": \"^1.0.5\",\n    \"@radix-ui/react-dropdown-menu\": \"^2.0.6\",\n    \"@radix-ui/react-label\": \"^2.0.2\",\n    \"@radix-ui/react-select\": \"^2.0.0\",\n    \"@radix-ui/react-separator\": \"^1.0.3\",\n    \"@radix-ui/react-slot\": \"^1.0.2\",\n    \"@radix-ui/react-toast\": \"^1.1.5\",\n    \"class-variance-authority\": \"^0.7.0\",\n    \"clsx\": \"^2.0.0\",\n    \"lucide-react\": \"^0.294.0\",\n    \"tailwind-merge\": \"^2.0.0\",\n    \"tailwindcss-animate\": \"^1.0.7\"\n  }\n}\n```\n\n### TSConfig Configuration\n\n```json\n{\n  \"compilerOptions\": {\n    \"target\": \"es5\",\n    \"lib\": [\"dom\", \"dom.iterable\", \"es6\"],\n    \"allowJs\": true,\n    \"skipLibCheck\": true,\n    \"strict\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"noEmit\": true,\n    \"esModuleInterop\": true,\n    \"module\": \"esnext\",\n    \"moduleResolution\": \"node\",\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"jsx\": \"preserve\",\n    \"incremental\": true,\n    \"plugins\": [\n      {\n        \"name\": \"next\"\n      }\n    ],\n    \"baseUrl\": \".\",\n    \"paths\": {\n      \"@/components/*\": [\"./src/components/*\"],\n      \"@/lib/*\": [\"./src/lib/*\"]\n    }\n  },\n  \"include\": [\"next-env.d.ts\", \"**/*.ts\", \"**/*.tsx\", \".next/types/**/*.ts\"],\n  \"exclude\": [\"node_modules\"]\n}\n```\n\n### Tailwind Configuration\n\n```js\n// tailwind.config.js\n/** @type {import(''tailwindcss'').Config} */\nmodule.exports = {\n  darkMode: [\"class\"],\n  content: [\n    ''./pages/**/*.{ts,tsx}'',\n    ''./components/**/*.{ts,tsx}'',\n    ''./app/**/*.{ts,tsx}'',\n    ''./src/**/*.{ts,tsx}'',\n  ],\n  prefix: \"\",\n  theme: {\n    container: {\n      center: true,\n      padding: \"2rem\",\n      screens: {\n        \"2xl\": \"1400px\",\n      },\n    },\n    extend: {\n      colors: {\n        border: \"hsl(var(--border))\",\n        input: \"hsl(var(--input))\",\n        ring: \"hsl(var(--ring))\",\n        background: \"hsl(var(--background))\",\n        foreground: \"hsl(var(--foreground))\",\n        primary: {\n          DEFAULT: \"hsl(var(--primary))\",\n          foreground: \"hsl(var(--primary-foreground))\",\n        },\n        secondary: {\n          DEFAULT: \"hsl(var(--secondary))\",\n          foreground: \"hsl(var(--secondary-foreground))\",\n        },\n        destructive: {\n          DEFAULT: \"hsl(var(--destructive))\",\n          foreground: \"hsl(var(--destructive-foreground))\",\n        },\n        muted: {\n          DEFAULT: \"hsl(var(--muted))\",\n          foreground: \"hsl(var(--muted-foreground))\",\n        },\n        accent: {\n          DEFAULT: \"hsl(var(--accent))\",\n          foreground: \"hsl(var(--accent-foreground))\",\n        },\n        popover: {\n          DEFAULT: \"hsl(var(--popover))\",\n          foreground: \"hsl(var(--popover-foreground))\",\n        },\n        card: {\n          DEFAULT: \"hsl(var(--card))\",\n          foreground: \"hsl(var(--card-foreground))\",\n        },\n      },\n      borderRadius: {\n        lg: \"var(--radius)\",\n        md: \"calc(var(--radius) - 2px)\",\n        sm: \"calc(var(--radius) - 4px)\",\n      },\n      keyframes: {\n        \"accordion-down\": {\n          from: { height: \"0\" },\n          to: { height: \"var(--radix-accordion-content-height)\" },\n        },\n        \"accordion-up\": {\n          from: { height: \"var(--radix-accordion-content-height)\" },\n          to: { height: \"0\" },\n        },\n      },\n      animation: {\n        \"accordion-down\": \"accordion-down 0.2s ease-out\",\n        \"accordion-up\": \"accordion-up 0.2s ease-out\",\n      },\n    },\n  },\n  plugins: [require(\"tailwindcss-animate\")],\n}\n```\n\n### CSS Variables (globals.css)\n\n```css\n@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n@layer base {\n  :root {\n    --background: 0 0% 100%;\n    --foreground: 222.2 84% 4.9%;\n    --card: 0 0% 100%;\n    --card-foreground: 222.2 84% 4.9%;\n    --popover: 0 0% 100%;\n    --popover-foreground: 222.2 84% 4.9%;\n    --primary: 222.2 47.4% 11.2%;\n    --primary-foreground: 210 40% 98%;\n    --secondary: 210 40% 96.1%;\n    --secondary-foreground: 222.2 47.4% 11.2%;\n    --muted: 210 40% 96.1%;\n    --muted-foreground: 215.4 16.3% 46.9%;\n    --accent: 210 40% 96.1%;\n    --accent-foreground: 222.2 47.4% 11.2%;\n    --destructive: 0 84.2% 60.2%;\n    --destructive-foreground: 210 40% 98%;\n    --border: 214.3 31.8% 91.4%;\n    --input: 214.3 31.8% 91.4%;\n    --ring: 222.2 84% 4.9%;\n    --radius: 0.5rem;\n  }\n\n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n    --card: 222.2 84% 4.9%;\n    --card-foreground: 210 40% 98%;\n    --popover: 222.2 84% 4.9%;\n    --popover-foreground: 210 40% 98%;\n    --primary: 210 40% 98%;\n    --primary-foreground: 222.2 47.4% 11.2%;\n    --secondary: 217.2 32.6% 17.5%;\n    --secondary-foreground: 210 40% 98%;\n    --muted: 217.2 32.6% 17.5%;\n    --muted-foreground: 215 20.2% 65.1%;\n    --accent: 217.2 32.6% 17.5%;\n    --accent-foreground: 210 40% 98%;\n    --destructive: 0 62.8% 30.6%;\n    --destructive-foreground: 210 40% 98%;\n    --border: 217.2 32.6% 17.5%;\n    --input: 217.2 32.6% 17.5%;\n    --ring: 212.7 26.8% 83.9%;\n  }\n}\n\n@layer base {\n  * {\n    @apply border-border;\n  }\n  body {\n    @apply bg-background text-foreground;\n  }\n}\n```\n\n## Core Components\n\n### Button Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add button\n```\n\nBasic usage:\n\n```tsx\nimport { Button } from \"@/components/ui/button\";\n\nexport function ButtonDemo() {\n  return <Button>Click me</Button>;\n}\n```\n\nButton variants:\n\n```tsx\nimport { Button } from \"@/components/ui/button\";\n\nexport function ButtonVariants() {\n  return (\n    <div className=\"flex gap-4\">\n      <Button variant=\"default\">Default</Button>\n      <Button variant=\"destructive\">Destructive</Button>\n      <Button variant=\"outline\">Outline</Button>\n      <Button variant=\"secondary\">Secondary</Button>\n      <Button variant=\"ghost\">Ghost</Button>\n      <Button variant=\"link\">Link</Button>\n    </div>\n  );\n}\n```\n\nButton sizes:\n\n```tsx\n<div className=\"flex gap-4 items-center\">\n  <Button size=\"default\">Default</Button>\n  <Button size=\"sm\">Small</Button>\n  <Button size=\"lg\">Large</Button>\n  <Button size=\"icon\">\n    <Icon className=\"h-4 w-4\" />\n  </Button>\n</div>\n```\n\nWith loading state:\n\n```tsx\nimport { Button } from \"@/components/ui/button\";\nimport { Loader2 } from \"lucide-react\";\n\nexport function ButtonLoading() {\n  return (\n    <Button disabled>\n      <Loader2 className=\"mr-2 h-4 w-4 animate-spin\" />\n      Please wait\n    </Button>\n  );\n}\n```\n\n### Input & Form Fields\n\n#### Input Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add input\n```\n\nBasic input:\n\n```tsx\nimport { Input } from \"@/components/ui/input\";\n\nexport function InputDemo() {\n  return <Input type=\"email\" placeholder=\"Email\" />;\n}\n```\n\nInput with label:\n\n```tsx\nimport { Input } from \"@/components/ui/input\";\nimport { Label } from \"@/components/ui/label\";\n\nexport function InputWithLabel() {\n  return (\n    <div className=\"grid w-full max-w-sm items-center gap-1.5\">\n      <Label htmlFor=\"email\">Email</Label>\n      <Input type=\"email\" id=\"email\" placeholder=\"Email\" />\n    </div>\n  );\n}\n```\n\nInput with button:\n\n```tsx\nimport { Button } from \"@/components/ui/button\";\nimport { Input } from \"@/components/ui/input\";\n\nexport function InputWithButton() {\n  return (\n    <div className=\"flex w-full max-w-sm items-center gap-2\">\n      <Input type=\"email\" placeholder=\"Email\" />\n      <Button type=\"submit\" variant=\"outline\">Subscribe</Button>\n    </div>\n  );\n}\n```\n\n### Forms with Validation\n\nInstallation:\n\n```bash\nnpx shadcn@latest add form\n```\n\nThis installs React Hook Form, Zod, and form components.\n\nComplete form example:\n\n```tsx\n\"use client\"\n\nimport { zodResolver } from \"@hookform/resolvers/zod\"\nimport { useForm } from \"react-hook-form\"\nimport * as z from \"zod\"\n\nimport { Button } from \"@/components/ui/button\"\nimport {\n  Form,\n  FormControl,\n  FormDescription,\n  FormField,\n  FormItem,\n  FormLabel,\n  FormMessage,\n} from \"@/components/ui/form\"\nimport { Input } from \"@/components/ui/input\"\nimport { toast } from \"@/components/ui/use-toast\"\n\nconst formSchema = z.object({\n  username: z.string().min(2, {\n    message: \"Username must be at least 2 characters.\",\n  }),\n  email: z.string().email({\n    message: \"Please enter a valid email address.\",\n  }),\n})\n\nexport function ProfileForm() {\n  const form = useForm<z.infer<typeof formSchema>>({\n    resolver: zodResolver(formSchema),\n    defaultValues: {\n      username: \"\",\n      email: \"\",\n    },\n  })\n\n  function onSubmit(values: z.infer<typeof formSchema>) {\n    toast({\n      title: \"You submitted the following values:\",\n      description: (\n        <pre className=\"mt-2 w-[340px] rounded-md bg-slate-950 p-4\">\n          <code className=\"text-white\">{JSON.stringify(values, null, 2)}</code>\n        </pre>\n      ),\n    })\n  }\n\n  return (\n    <Form {...form}>\n      <form onSubmit={form.handleSubmit(onSubmit)} className=\"space-y-8\">\n        <FormField\n          control={form.control}\n          name=\"username\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Username</FormLabel>\n              <FormControl>\n                <Input placeholder=\"shadcn\" {...field} />\n              </FormControl>\n              <FormDescription>\n                This is your public display name.\n              </FormDescription>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n        \n        <FormField\n          control={form.control}\n          name=\"email\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Email</FormLabel>\n              <FormControl>\n                <Input type=\"email\" placeholder=\"you@example.com\" {...field} />\n              </FormControl>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n        \n        <Button type=\"submit\">Submit</Button>\n      </form>\n    </Form>\n  )\n}\n```\n\n### Card Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add card\n```\n\nBasic card:\n\n```tsx\nimport {\n  Card,\n  CardContent,\n  CardDescription,\n  CardFooter,\n  CardHeader,\n  CardTitle,\n} from \"@/components/ui/card\"\n\nexport function CardDemo() {\n  return (\n    <Card>\n      <CardHeader>\n        <CardTitle>Card Title</CardTitle>\n        <CardDescription>Card Description</CardDescription>\n      </CardHeader>\n      <CardContent>\n        <p>Card Content</p>\n      </CardContent>\n      <CardFooter>\n        <p>Card Footer</p>\n      </CardFooter>\n    </Card>\n  )\n}\n```\n\nCard with form:\n\n```tsx\nimport { Button } from \"@/components/ui/button\"\nimport {\n  Card,\n  CardContent,\n  CardDescription,\n  CardFooter,\n  CardHeader,\n  CardTitle,\n} from \"@/components/ui/card\"\nimport { Input } from \"@/components/ui/input\"\nimport { Label } from \"@/components/ui/label\"\n\nexport function CardWithForm() {\n  return (\n    <Card className=\"w-[350px]\">\n      <CardHeader>\n        <CardTitle>Create project</CardTitle>\n        <CardDescription>Deploy your new project in one-click.</CardDescription>\n      </CardHeader>\n      <CardContent>\n        <form>\n          <div className=\"grid w-full items-center gap-4\">\n            <div className=\"flex flex-col space-y-1.5\">\n              <Label htmlFor=\"name\">Name</Label>\n              <Input id=\"name\" placeholder=\"Name of your project\" />\n            </div>\n          </div>\n        </form>\n      </CardContent>\n      <CardFooter className=\"flex justify-between\">\n        <Button variant=\"outline\">Cancel</Button>\n        <Button>Deploy</Button>\n      </CardFooter>\n    </Card>\n  )\n}\n```\n\n### Dialog (Modal) Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add dialog\n```\n\nBasic dialog:\n\n```tsx\nimport { Button } from \"@/components/ui/button\"\nimport {\n  Dialog,\n  DialogContent,\n  DialogDescription,\n  DialogFooter,\n  DialogHeader,\n  DialogTitle,\n  DialogTrigger,\n} from \"@/components/ui/dialog\"\n\nexport function DialogDemo() {\n  return (\n    <Dialog>\n      <DialogTrigger asChild>\n        <Button variant=\"outline\">Open Dialog</Button>\n      </DialogTrigger>\n      <DialogContent className=\"sm:max-w-[425px]\">\n        <DialogHeader>\n          <DialogTitle>Edit profile</DialogTitle>\n          <DialogDescription>\n            Make changes to your profile here. Click save when you''re done.\n          </DialogDescription>\n        </DialogHeader>\n        <div className=\"grid gap-4 py-4\">\n          <div className=\"grid grid-cols-4 items-center gap-4\">\n            <Label htmlFor=\"name\" className=\"text-right\">\n              Name\n            </Label>\n            <Input id=\"name\" value=\"Pedro Duarte\" className=\"col-span-3\" />\n          </div>\n        </div>\n        <DialogFooter>\n          <Button type=\"submit\">Save changes</Button>\n        </DialogFooter>\n      </DialogContent>\n    </Dialog>\n  )\n}\n```\n\n### Sheet (Slide-over) Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add sheet\n```\n\nBasic sheet:\n\n```tsx\nimport { Button } from \"@/components/ui/button\"\nimport {\n  Sheet,\n  SheetContent,\n  SheetDescription,\n  SheetHeader,\n  SheetTitle,\n  SheetTrigger,\n} from \"@/components/ui/sheet\"\n\nexport function SheetDemo() {\n  return (\n    <Sheet>\n      <SheetTrigger asChild>\n        <Button variant=\"outline\">Open Sheet</Button>\n      </SheetTrigger>\n      <SheetContent>\n        <SheetHeader>\n          <SheetTitle>Edit profile</SheetTitle>\n          <SheetDescription>\n            Make changes to your profile here. Click save when you''re done.\n          </SheetDescription>\n        </SheetHeader>\n        <div className=\"grid gap-4 py-4\">\n          <div className=\"grid grid-cols-4 items-center gap-4\">\n            <Label htmlFor=\"name\" className=\"text-right\">\n              Name\n            </Label>\n            <Input id=\"name\" value=\"Pedro Duarte\" className=\"col-span-3\" />\n          </div>\n          <div className=\"grid grid-cols-4 items-center gap-4\">\n            <Label htmlFor=\"username\" className=\"text-right\">\n              Username\n            </Label>\n            <Input id=\"username\" value=\"@peduarte\" className=\"col-span-3\" />\n          </div>\n        </div>\n      </SheetContent>\n    </Sheet>\n  )\n}\n```\n\nSheet with side placement:\n\n```tsx\n<Sheet>\n  <SheetTrigger asChild>\n    <Button variant=\"outline\">Open Right Sheet</Button>\n  </SheetTrigger>\n  <SheetContent side=\"right\">\n    <SheetHeader>\n      <SheetTitle>Settings</SheetTitle>\n      <SheetDescription>\n        Configure your application settings here.\n      </SheetDescription>\n    </SheetHeader>\n    {/* Settings content */}\n  </SheetContent>\n</Sheet>\n```\n\n### Menubar & Navigation\n\n#### Menubar Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add menubar\n```\n\nBasic menubar:\n\n```tsx\nimport {\n  Menubar,\n  MenubarContent,\n  MenubarItem,\n  MenubarMenu,\n  MenubarSeparator,\n  MenubarShortcut,\n  MenubarSub,\n  MenubarSubContent,\n  MenubarSubTrigger,\n  MenubarTrigger,\n} from \"@/components/ui/menubar\"\n\nexport function MenubarDemo() {\n  return (\n    <Menubar>\n      <MenubarMenu>\n        <MenubarTrigger>File</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>\n            New Tab <MenubarShortcut>⌘T</MenubarShortcut>\n          </MenubarItem>\n          <MenubarItem>\n            New Window <MenubarShortcut>⌘N</MenubarShortcut>\n          </MenubarItem>\n          <MenubarSeparator />\n          <MenubarItem>Share</MenubarItem>\n          <MenubarSeparator />\n          <MenubarItem>Print</MenubarItem>\n        </MenubarContent>\n      </MenubarMenu>\n      <MenubarMenu>\n        <MenubarTrigger>Edit</MenubarTrigger>\n        <MenubarContent>\n          <MenubarItem>\n            Undo <MenubarShortcut>⌘Z</MenubarShortcut>\n          </MenubarItem>\n          <MenubarItem>\n            Redo <MenubarShortcut>⌘Y</MenubarShortcut>\n          </MenubarItem>\n          <MenubarSeparator />\n          <MenubarSub>\n            <MenubarSubTrigger>Find</MenubarSubTrigger>\n            <MenubarSubContent>\n              <MenubarItem>Search the web</MenubarItem>\n              <MenubarItem>Find...</MenubarItem>\n              <MenubarItem>Find Next</MenubarItem>\n              <MenubarItem>Find Previous</MenubarItem>\n            </MenubarSubContent>\n          </MenubarSub>\n        </MenubarContent>\n      </MenubarMenu>\n    </Menubar>\n  )\n}\n```\n\n### Select (Dropdown) Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add select\n```\n\nBasic select:\n\n```tsx\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectTrigger,\n  SelectValue,\n} from \"@/components/ui/select\"\n\nexport function SelectDemo() {\n  return (\n    <Select>\n      <SelectTrigger className=\"w-[180px]\">\n        <SelectValue placeholder=\"Select a fruit\" />\n      </SelectTrigger>\n      <SelectContent>\n        <SelectItem value=\"apple\">Apple</SelectItem>\n        <SelectItem value=\"banana\">Banana</SelectItem>\n        <SelectItem value=\"orange\">Orange</SelectItem>\n      </SelectContent>\n    </Select>\n  )\n}\n```\n\nSelect in form:\n\n```tsx\n<FormField\n  control={form.control}\n  name=\"role\"\n  render={({ field }) => (\n    <FormItem>\n      <FormLabel>Role</FormLabel>\n      <Select onValueChange={field.onChange} defaultValue={field.value}>\n        <FormControl>\n          <SelectTrigger>\n            <SelectValue placeholder=\"Select a role\" />\n          </SelectTrigger>\n        </FormControl>\n        <SelectContent>\n          <SelectItem value=\"admin\">Admin</SelectItem>\n          <SelectItem value=\"user\">User</SelectItem>\n          <SelectItem value=\"guest\">Guest</SelectItem>\n        </SelectContent>\n      </Select>\n      <FormMessage />\n    </FormItem>\n  )}\n/>\n```\n\n### Toast Notifications\n\nInstallation:\n\n```bash\nnpx shadcn@latest add toast\n```\n\nSetup toast provider in root layout:\n\n```tsx\nimport { Toaster } from \"@/components/ui/toaster\"\n\nexport default function RootLayout({ children }) {\n  return (\n    <html lang=\"en\">\n      <body>\n        {children}\n        <Toaster />\n      </body>\n    </html>\n  )\n}\n```\n\nUsing toast:\n\n```tsx\nimport { useToast } from \"@/components/ui/use-toast\"\nimport { Button } from \"@/components/ui/button\"\n\nexport function ToastDemo() {\n  const { toast } = useToast()\n\n  return (\n    <Button\n      onClick={() => {\n        toast({\n          title: \"Scheduled: Catch up\",\n          description: \"Friday, February 10, 2023 at 5:57 PM\",\n        })\n      }}\n    >\n      Show Toast\n    </Button>\n  )\n}\n```\n\nToast variants:\n\n```tsx\n// Success\ntoast({\n  title: \"Success\",\n  description: \"Your changes have been saved.\",\n})\n\n// Error\ntoast({\n  variant: \"destructive\",\n  title: \"Error\",\n  description: \"Something went wrong.\",\n})\n\n// With action\ntoast({\n  title: \"Uh oh! Something went wrong.\",\n  description: \"There was a problem with your request.\",\n  action: <ToastAction altText=\"Try again\">Try again</ToastAction>,\n})\n```\n\n### Table Component\n\nInstallation:\n\n```bash\nnpx shadcn@latest add table\n```\n\nBasic table:\n\n```tsx\nimport {\n  Table,\n  TableBody,\n  TableCaption,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"@/components/ui/table\"\n\nconst invoices = [\n  { invoice: \"INV001\", status: \"Paid\", method: \"Credit Card\", amount: \"$250.00\" },\n  { invoice: \"INV002\", status: \"Pending\", method: \"PayPal\", amount: \"$150.00\" },\n]\n\nexport function TableDemo() {\n  return (\n    <Table>\n      <TableCaption>A list of your recent invoices.</TableCaption>\n      <TableHeader>\n        <TableRow>\n          <TableHead>Invoice</TableHead>\n          <TableHead>Status</TableHead>\n          <TableHead>Method</TableHead>\n          <TableHead className=\"text-right\">Amount</TableHead>\n        </TableRow>\n      </TableHeader>\n      <TableBody>\n        {invoices.map((invoice) => (\n          <TableRow key={invoice.invoice}>\n            <TableCell className=\"font-medium\">{invoice.invoice}</TableCell>\n            <TableCell>{invoice.status}</TableCell>\n            <TableCell>{invoice.method}</TableCell>\n            <TableCell className=\"text-right\">{invoice.amount}</TableCell>\n          </TableRow>\n        ))}\n      </TableBody>\n    </Table>\n  )\n}\n```\n\n## Customization\n\n### Theming with CSS Variables\n\nshadcn/ui uses CSS variables for theming. Configure in `globals.css`:\n\n```css\n@layer base {\n  :root {\n    --background: 0 0% 100%;\n    --foreground: 222.2 84% 4.9%;\n    --primary: 222.2 47.4% 11.2%;\n    --primary-foreground: 210 40% 98%;\n    --secondary: 210 40% 96.1%;\n    --secondary-foreground: 222.2 47.4% 11.2%;\n    --muted: 210 40% 96.1%;\n    --muted-foreground: 215.4 16.3% 46.9%;\n    --accent: 210 40% 96.1%;\n    --accent-foreground: 222.2 47.4% 11.2%;\n    --destructive: 0 84.2% 60.2%;\n    --destructive-foreground: 210 40% 98%;\n    --border: 214.3 31.8% 91.4%;\n    --input: 214.3 31.8% 91.4%;\n    --ring: 222.2 84% 4.9%;\n    --radius: 0.5rem;\n  }\n\n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n    --primary: 210 40% 98%;\n    --primary-foreground: 222.2 47.4% 11.2%;\n    /* ... other dark mode variables */\n  }\n}\n```\n\n### Customizing Components\n\nSince you own the code, customize directly:\n\n```tsx\n// components/ui/button.tsx\nimport * as React from \"react\"\nimport { Slot } from \"@radix-ui/react-slot\"\nimport { cva, type VariantProps } from \"class-variance-authority\"\nimport { cn } from \"@/lib/utils\"\n\nconst buttonVariants = cva(\n  \"inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground hover:bg-primary/90\",\n        destructive: \"bg-destructive text-destructive-foreground hover:bg-destructive/90\",\n        outline: \"border border-input bg-background hover:bg-accent\",\n        // Add custom variant\n        custom: \"bg-gradient-to-r from-purple-500 to-pink-500 text-white\",\n      },\n      size: {\n        default: \"h-10 px-4 py-2\",\n        sm: \"h-9 rounded-md px-3\",\n        lg: \"h-11 rounded-md px-8\",\n        // Add custom size\n        xl: \"h-14 rounded-md px-10 text-lg\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n)\n\nexport interface ButtonProps\n  extends React.ButtonHTMLAttributes<HTMLButtonElement>,\n    VariantProps<typeof buttonVariants> {\n  asChild?: boolean\n}\n\nconst Button = React.forwardRef<HTMLButtonElement, ButtonProps>(\n  ({ className, variant, size, asChild = false, ...props }, ref) => {\n    const Comp = asChild ? Slot : \"button\"\n    return (\n      <Comp\n        className={cn(buttonVariants({ variant, size, className }))}\n        ref={ref}\n        {...props}\n      />\n    )\n  }\n)\nButton.displayName = \"Button\"\n\nexport { Button, buttonVariants }\n```\n\n## Next.js Integration\n\n### App Router Setup\n\nFor Next.js 13+ with App Router, ensure components use `\"use client\"` directive:\n\n```tsx\n// src/components/ui/button.tsx\n\"use client\"\n\nimport * as React from \"react\"\nimport { Slot } from \"@radix-ui/react-slot\"\nimport { cva, type VariantProps } from \"class-variance-authority\"\nimport { cn } from \"@/lib/utils\"\n\n// ... rest of component\n```\n\n### Layout Integration\n\nAdd the Toaster to your root layout:\n\n```tsx\n// app/layout.tsx\nimport { Toaster } from \"@/components/ui/toaster\"\nimport \"./globals.css\"\n\nexport default function RootLayout({\n  children,\n}: {\n  children: React.ReactNode\n}) {\n  return (\n    <html lang=\"en\" suppressHydrationWarning>\n      <body className=\"min-h-screen bg-background font-sans antialiased\">\n        {children}\n        <Toaster />\n      </body>\n    </html>\n  )\n}\n```\n\n### Server Components\n\nWhen using shadcn/ui components in Server Components, wrap them in a Client Component:\n\n```tsx\n// app/dashboard/page.tsx\nimport { Card, CardContent, CardHeader, CardTitle } from \"@/components/ui/card\"\nimport { ButtonClient } from \"@/components/ui/button-client\"\n\nexport default function DashboardPage() {\n  return (\n    <div className=\"container mx-auto p-6\">\n      <Card>\n        <CardHeader>\n          <CardTitle>Dashboard</CardTitle>\n        </CardHeader>\n        <CardContent>\n          <ButtonClient>Interactive Button</ButtonClient>\n        </CardContent>\n      </Card>\n    </div>\n  )\n}\n```\n\n```tsx\n// src/components/ui/button-client.tsx\n\"use client\"\n\nimport { Button } from \"./button\"\n\nexport function ButtonClient(props: React.ComponentProps<typeof Button>) {\n  return <Button {...props} />\n}\n```\n\n### Route Handlers with Forms\n\nCreate API routes for form submissions:\n\n```tsx\n// app/api/contact/route.ts\nimport { NextRequest, NextResponse } from \"next/server\"\nimport { z } from \"zod\"\n\nconst contactSchema = z.object({\n  name: z.string().min(2),\n  email: z.string().email(),\n  message: z.string().min(10),\n})\n\nexport async function POST(request: NextRequest) {\n  try {\n    const body = await request.json()\n    const validated = contactSchema.parse(body)\n\n    // Process form data\n    console.log(\"Form submission:\", validated)\n\n    return NextResponse.json({ success: true })\n  } catch (error) {\n    if (error instanceof z.ZodError) {\n      return NextResponse.json(\n        { errors: error.errors },\n        { status: 400 }\n      )\n    }\n\n    return NextResponse.json(\n      { error: \"Internal server error\" },\n      { status: 500 }\n    )\n  }\n}\n```\n\n### Form with Server Action\n\nUsing Next.js 14+ Server Actions:\n\n```tsx\n// app/contact/page.tsx\n\"use client\"\n\nimport { zodResolver } from \"@hookform/resolvers/zod\"\nimport { useForm } from \"react-hook-form\"\nimport * as z from \"zod\"\nimport { Button } from \"@/components/ui/button\"\nimport {\n  Form,\n  FormControl,\n  FormField,\n  FormItem,\n  FormLabel,\n  FormMessage,\n} from \"@/components/ui/form\"\nimport { Input } from \"@/components/ui/input\"\nimport { Textarea } from \"@/components/ui/textarea\"\nimport { toast } from \"@/components/ui/use-toast\"\n\nconst formSchema = z.object({\n  name: z.string().min(2),\n  email: z.string().email(),\n  message: z.string().min(10),\n})\n\nasync function onSubmit(values: z.infer<typeof formSchema>) {\n  try {\n    const response = await fetch(\"/api/contact\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(values),\n    })\n\n    if (!response.ok) throw new Error(\"Failed to submit\")\n\n    toast({\n      title: \"Success!\",\n      description: \"Your message has been sent.\",\n    })\n  } catch (error) {\n    toast({\n      variant: \"destructive\",\n      title: \"Error\",\n      description: \"Failed to send message. Please try again.\",\n    })\n  }\n}\n\nexport default function ContactPage() {\n  const form = useForm<z.infer<typeof formSchema>>({\n    resolver: zodResolver(formSchema),\n  })\n\n  return (\n    <div className=\"container mx-auto max-w-2xl py-8\">\n      <Form {...form}>\n        <form onSubmit={form.handleSubmit(onSubmit)} className=\"space-y-6\">\n          <FormField\n            control={form.control}\n            name=\"name\"\n            render={({ field }) => (\n              <FormItem>\n                <FormLabel>Name</FormLabel>\n                <FormControl>\n                  <Input placeholder=\"Your name\" {...field} />\n                </FormControl>\n                <FormMessage />\n              </FormItem>\n            )}\n          />\n\n          <FormField\n            control={form.control}\n            name=\"email\"\n            render={({ field }) => (\n              <FormItem>\n                <FormLabel>Email</FormLabel>\n                <FormControl>\n                  <Input type=\"email\" placeholder=\"your@email.com\" {...field} />\n                </FormControl>\n                <FormMessage />\n              </FormItem>\n            )}\n          />\n\n          <FormField\n            control={form.control}\n            name=\"message\"\n            render={({ field }) => (\n              <FormItem>\n                <FormLabel>Message</FormLabel>\n                <FormControl>\n                  <Textarea\n                    placeholder=\"Your message...\"\n                    className=\"resize-none\"\n                    {...field}\n                  />\n                </FormControl>\n                <FormMessage />\n              </FormItem>\n            )}\n          />\n\n          <Button type=\"submit\" className=\"w-full\">\n            Send Message\n          </Button>\n        </form>\n      </Form>\n    </div>\n  )\n}\n```\n\n### Metadata with shadcn/ui\n\nUsing shadcn/ui components in metadata:\n\n```tsx\n// app/layout.tsx\nimport { Metadata } from \"next\"\n\nexport const metadata: Metadata = {\n  title: {\n    default: \"My App\",\n    template: \"%s | My App\",\n  },\n  description: \"Built with shadcn/ui and Next.js\",\n}\n\n// app/about/page.tsx\nimport { Metadata } from \"next\"\nimport { Card, CardContent, CardHeader, CardTitle } from \"@/components/ui/card\"\n\nexport const metadata: Metadata = {\n  title: \"About Us\",\n  description: \"Learn more about our company\",\n}\n\nexport default function AboutPage() {\n  return (\n    <div className=\"container mx-auto py-8\">\n      <Card>\n        <CardHeader>\n          <CardTitle>About Our Company</CardTitle>\n        </CardHeader>\n        <CardContent>\n          <p>We build amazing products with modern web technologies.</p>\n        </CardContent>\n      </Card>\n    </div>\n  )\n}\n```\n\n### Font Optimization\n\nOptimize fonts with next/font:\n\n```tsx\n// app/layout.tsx\nimport { Inter } from \"next/font/google\"\nimport { Toaster } from \"@/components/ui/toaster\"\nimport { cn } from \"@/lib/utils\"\nimport \"./globals.css\"\n\nconst inter = Inter({ subsets: [\"latin\"] })\n\nexport default function RootLayout({\n  children,\n}: {\n  children: React.ReactNode\n}) {\n  return (\n    <html lang=\"en\" suppressHydrationWarning>\n      <body className={cn(\"min-h-screen bg-background font-sans antialiased\", inter.className)}>\n        {children}\n        <Toaster />\n      </body>\n    </html>\n  )\n}\n```\n\n## Advanced Patterns\n\n### Form with Multiple Fields\n\n```tsx\nconst formSchema = z.object({\n  username: z.string().min(2).max(50),\n  email: z.string().email(),\n  bio: z.string().max(160).min(4),\n  role: z.enum([\"admin\", \"user\", \"guest\"]),\n  notifications: z.boolean().default(false),\n})\n\nexport function AdvancedForm() {\n  const form = useForm<z.infer<typeof formSchema>>({\n    resolver: zodResolver(formSchema),\n    defaultValues: {\n      username: \"\",\n      email: \"\",\n      bio: \"\",\n      role: \"user\",\n      notifications: false,\n    },\n  })\n\n  function onSubmit(values: z.infer<typeof formSchema>) {\n    console.log(values)\n  }\n\n  return (\n    <Form {...form}>\n      <form onSubmit={form.handleSubmit(onSubmit)} className=\"space-y-8\">\n        {/* Username field */}\n        <FormField\n          control={form.control}\n          name=\"username\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Username</FormLabel>\n              <FormControl>\n                <Input placeholder=\"johndoe\" {...field} />\n              </FormControl>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n\n        {/* Email field */}\n        <FormField\n          control={form.control}\n          name=\"email\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Email</FormLabel>\n              <FormControl>\n                <Input type=\"email\" placeholder=\"john@example.com\" {...field} />\n              </FormControl>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n\n        {/* Textarea field */}\n        <FormField\n          control={form.control}\n          name=\"bio\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Bio</FormLabel>\n              <FormControl>\n                <Textarea\n                  placeholder=\"Tell us about yourself\"\n                  className=\"resize-none\"\n                  {...field}\n                />\n              </FormControl>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n\n        {/* Select field */}\n        <FormField\n          control={form.control}\n          name=\"role\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Role</FormLabel>\n              <Select onValueChange={field.onChange} defaultValue={field.value}>\n                <FormControl>\n                  <SelectTrigger>\n                    <SelectValue placeholder=\"Select a role\" />\n                  </SelectTrigger>\n                </FormControl>\n                <SelectContent>\n                  <SelectItem value=\"admin\">Admin</SelectItem>\n                  <SelectItem value=\"user\">User</SelectItem>\n                  <SelectItem value=\"guest\">Guest</SelectItem>\n                </SelectContent>\n              </Select>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n\n        {/* Checkbox field */}\n        <FormField\n          control={form.control}\n          name=\"notifications\"\n          render={({ field }) => (\n            <FormItem className=\"flex flex-row items-start space-x-3 space-y-0\">\n              <FormControl>\n                <Checkbox\n                  checked={field.value}\n                  onCheckedChange={field.onChange}\n                />\n              </FormControl>\n              <div className=\"space-y-1 leading-none\">\n                <FormLabel>Email notifications</FormLabel>\n                <FormDescription>\n                  Receive emails about your account activity.\n                </FormDescription>\n              </div>\n            </FormItem>\n          )}\n        />\n\n        <Button type=\"submit\">Submit</Button>\n      </form>\n    </Form>\n  )\n}\n```\n\n## Best Practices\n\n1. **Accessibility**: Components use Radix UI primitives for ARIA compliance\n2. **Customization**: Modify components directly in your codebase\n3. **Type Safety**: Use TypeScript for type-safe props and state\n4. **Validation**: Use Zod schemas for form validation\n5. **Styling**: Leverage Tailwind utilities and CSS variables\n6. **Consistency**: Use the same component patterns across your app\n7. **Testing**: Components are testable with React Testing Library\n8. **Performance**: Components are optimized and tree-shakeable\n\n## Common Component Combinations\n\n### Login Form\n\n```tsx\n<Card className=\"w-[350px]\">\n  <CardHeader>\n    <CardTitle>Login</CardTitle>\n    <CardDescription>Enter your credentials to continue</CardDescription>\n  </CardHeader>\n  <CardContent>\n    <Form {...form}>\n      <form onSubmit={form.handleSubmit(onSubmit)} className=\"space-y-4\">\n        <FormField\n          control={form.control}\n          name=\"email\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Email</FormLabel>\n              <FormControl>\n                <Input type=\"email\" placeholder=\"you@example.com\" {...field} />\n              </FormControl>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n        <FormField\n          control={form.control}\n          name=\"password\"\n          render={({ field }) => (\n            <FormItem>\n              <FormLabel>Password</FormLabel>\n              <FormControl>\n                <Input type=\"password\" {...field} />\n              </FormControl>\n              <FormMessage />\n            </FormItem>\n          )}\n        />\n        <Button type=\"submit\" className=\"w-full\">Login</Button>\n      </form>\n    </Form>\n  </CardContent>\n</Card>\n```\n\n## References\n\n- Official Docs: https://ui.shadcn.com\n- Radix UI: https://www.radix-ui.com\n- React Hook Form: https://react-hook-form.com\n- Zod: https://zod.dev\n- Tailwind CSS: https://tailwindcss.com\n- Examples: https://ui.shadcn.com/examples\n"},"lastSynced":"2026-02-18T10:20:25.615Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents needing to build accessible and customizable UI components with shadcn/ui, Radix UI, and Tailwind CSS.","zh":"适用于需要构建可访问和可自定义UI组件的前端代理，使用shadcn/ui、Radix UI和Tailwind CSS。","ja":"フロントエンドエージェントがshadcn/ui、Radix UI、Tailwind CSSを使用してアクセシブルでカスタマイズ可能なUIコンポーネントを構築する場合に適しています。","ko":"shadcn/ui, Radix UI 및 Tailwind CSS를 사용하여 접근 가능하고 사용자 지정 가능한 UI 구성 요소를 구축해야 하는 프론트 엔드 에이전트에 적합합니다.","es":"Ideal para agentes frontend que necesitan crear componentes de UI personalizables y accesibles con shadcn/ui, Radix UI y Tailwind CSS.","fr":"Idéal pour les agents frontend qui ont besoin de créer des composants d''interface utilisateur personnalisables et accessibles avec shadcn/ui, Radix UI et Tailwind CSS.","de":"Ideal für Frontend-Agents, die zugängliche und anpassbare UI-Komponenten mit shadcn/ui, Radix UI und Tailwind CSS erstellen müssen.","pt":"Ideal para Agentes Frontend que precisam criar componentes de UI acessíveis e personalizáveis com shadcn/ui, Radix UI e Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, которым необходимо создавать доступные и настраиваемые компоненты UI с помощью shadcn/ui, Radix UI и Tailwind CSS.","ar":"مثالية لعمال الواجهة الأمامية الذين يحتاجون إلى إنشاء مكونات واجهة المستخدم القابلة للوصول والتعديل باستخدام shadcn/ui و Radix UI و Tailwind CSS."},"recommendation":{"en":"Empowers agents to create responsive and accessible interfaces using shadcn/ui component patterns, leveraging Radix UI and Tailwind CSS for enhanced customization and styling capabilities, including buttons, input fields, and forms with validation.","zh":"赋予代理创建响应式和可访问的界面使用shadcn/ui组件模式，利用Radix UI和Tailwind CSS进行增强的自定义和样式功能，包括按钮、输入字段和带有验证的表单。","ja":"shadcn/uiコンポーネントパターンを使用して、Radix UIとTailwind CSSを活用してカスタマイズとスタイリング機能を強化した、レスポンシブでアクセシブルなインターフェイスを作成できるようにエージェントに権限を付与します。ボタン、入力フィールド、フォームの検証が含まれます。","ko":"에이전트가 shadcn/ui 컴포넌트 패턴을 사용하여 반응형 및 접근 가능한 인터페이스를 생성할 수 있도록하며, Radix UI 및 Tailwind CSS를 사용하여 커스터마이즈 및 스타일 기능을 강화하고, 버튼, 입력 필드 및 유효성 검사와 같은 양식을 포함합니다.","es":"Habilita a los agentes a crear interfaces responsivas y accesibles utilizando patrones de componentes shadcn/ui, aprovechando Radix UI y Tailwind CSS para mejorar las capacidades de personalización y estilo, incluyendo botones, campos de entrada y formularios con validación.","fr":"Permet aux agents de créer des interfaces réactives et accessibles en utilisant des modèles de composants shadcn/ui, en exploitant Radix UI et Tailwind CSS pour améliorer les capacités de personnalisation et de style, y compris les boutons, les champs de saisie et les formulaires avec validation.","de":"Ermächtigt Agenten, responsive und zugängliche Schnittstellen zu erstellen, indem sie shadcn/ui-Komponentenmuster verwenden, Radix UI und Tailwind CSS für erweiterte Anpassungs- und Stilfunktionen nutzt, einschließlich Schaltflächen, Eingabefeldern und Formularen mit Validierung.","pt":"Habilita os agentes a criar interfaces responsivas e acessíveis usando padrões de componentes shadcn/ui, aproveitando Radix UI e Tailwind CSS para capacidades de personalização e estilização aprimoradas, incluindo botões, campos de entrada e formulários com validação.","ru":"Наделяет агентов возможностью создавать отзывчивые и доступные интерфейсы с помощью шаблонов компонентов shadcn/ui, используя Radix UI и Tailwind CSS для улучшения возможностей настройки и стилизации, включая кнопки, поля ввода и формы с валидацией.","ar":"تمكن العمال من إنشاء واجهات مستخدم مستجية وقابلة للوصول باستخدام أنماط مكونات shadcn/ui، مع الاستفادة من Radix UI و Tailwind CSS لتحسين القدرات التعديلية والتنسيقية، بما في ذلك الأزرار وحقول الإدخال والاستمارات مع التحقق."},"useCases":{"en":["Building customizable button components with shadcn/ui","Generating accessible form fields and validation using Radix UI and Tailwind CSS","Creating responsive card components with shadcn/ui and Tailwind CSS styling"],"zh":["使用shadcn/ui构建可自定义的按钮组件","使用Radix UI和Tailwind CSS生成可访问的表单字段和验证","使用shadcn/ui和Tailwind CSS样式创建响应式卡片组件"],"ja":["shadcn/uiを使用してカスタマイズ可能なボタンのコンポーネントを構築する","Radix UIとTailwind CSSを使用してアクセシブルなフォームフィールドと検証を生成する","shadcn/uiとTailwind CSSのスタイリングを使用してレスポンシブなカードコンポーネントを作成する"],"ko":["shadcn/ui를 사용하여 사용자 지정 가능한 버튼 구성 요소를 구축하는 것","Radix UI 및 Tailwind CSS를 사용하여 접근 가능한 양식 필드 및 유효성 검사를 생성하는 것","shadcn/ui 및 Tailwind CSS 스타일을 사용하여 반응형 카드 구성 요소를 생성하는 것"],"es":["Creación de componentes de botones personalizables con shadcn/ui","Generación de campos de formulario accesibles y validación utilizando Radix UI y Tailwind CSS","Creación de componentes de tarjetas responsivas con estilos shadcn/ui y Tailwind CSS"],"fr":["Création de composants de boutons personnalisables avec shadcn/ui","Génération de champs de formulaire accessibles et de validation en utilisant Radix UI et Tailwind CSS","Création de composants de cartes réactives avec des styles shadcn/ui et Tailwind CSS"],"de":["Erstellung von anpassbaren Schaltflächen-Komponenten mit shadcn/ui","Erstellung von zugänglichen Formularfeldern und Validierung unter Verwendung von Radix UI und Tailwind CSS","Erstellung von responsiven Karten-Komponenten mit shadcn/ui- und Tailwind CSS-Stilen"],"pt":["Construir componentes de botão personalizáveis com shadcn/ui","Gerar campos de formulário acessíveis e validação usando Radix UI e Tailwind CSS","Criar componentes de cartão responsivos com estilização shadcn/ui e Tailwind CSS"],"ru":["Создание настраиваемых компонентов кнопок с помощью shadcn/ui","Генерация доступных полей формы и валидация с помощью Radix UI и Tailwind CSS","Создание отзывчивых компонентов карточек с помощью shadcn/ui и стилизацией Tailwind CSS"],"ar":["بناء مكونات زر مخصصة باستخدام shadcn/ui","генерация حقول استمارة قابلة للوصول والتحقق باستخدام Radix UI و Tailwind CSS","إنشاء مكونات بطاقة مستجيب مع تنسيق shadcn/ui و Tailwind CSS"]},"limitations":{"en":["Requires installation and setup of shadcn/ui, Radix UI, and Tailwind CSS","Limited to frontend development and UI component customization"],"zh":["需要安装和设置shadcn/ui、Radix UI和Tailwind CSS","仅限于前端开发和UI组件自定义"],"ja":["shadcn/ui、Radix UI、Tailwind CSSのインストールとセットアップが必要","フロントエンド開発とUIコンポーネントのカスタマイズに限定される"],"ko":["shadcn/ui, Radix UI 및 Tailwind CSS의 설치 및 설정이 필요함","프론트 엔드 개발 및 UI 구성 요소 사용자 지정에만 제한됨"],"es":["Requiere la instalación y configuración de shadcn/ui, Radix UI y Tailwind CSS","Limitado al desarrollo frontend y la personalización de componentes de UI"],"fr":["Nécessite l''installation et la configuration de shadcn/ui, Radix UI et Tailwind CSS","Limité au développement frontend et à la personnalisation des composants d''interface utilisateur"],"de":["Erfordert die Installation und Einrichtung von shadcn/ui, Radix UI und Tailwind CSS","Begrenzt auf die Frontend-Entwicklung und die Anpassung von UI-Komponenten"],"pt":["Exige instalação e configuração de shadcn/ui, Radix UI e Tailwind CSS","Limitado ao desenvolvimento frontend e personalização de componentes de UI"],"ru":["Требует установки и настройки shadcn/ui, Radix UI и Tailwind CSS","Ограничен разработкой frontend и настройкой компонентов UI"],"ar":["يتطلب تثبيت وإعداد shadcn/ui و Radix UI و Tailwind CSS","محدود بالتطوير الأمامي وتعديل مكونات واجهة المستخدم"]},"version":3},"qualityScore":70}');
