INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('razorpay/blade/review-changes', 'community', 'razorpay', 'blade', 'razorpay/blade', 'review-changes', 0, 0, 65, '2026-02-18T01:08:43.488Z', '2026-02-18T10:21:39.342Z', NULL, '{"id":"razorpay/blade/review-changes","name":"review-changes","description":{"zh":"Review Changes 技术用于优化 Razorpay 设计系统的代码审查流程，通过检查 CI 状态和提取 Storybook 预览 URL","ja":"変更レビューティクは、Razorpay デザインシステムのコードレビューのプロセスを最適化するために使用され、CI 状態の確認と Storybook プレビュー URL の抽出を行う","ko":"변경 리뷰 기술은 Razorpay 디자인 시스템의 코드 리뷰 프로세스를 최적화 하기 위해 사용되며, CI 상태 확인 및 Storybook预览 URL 추출을 수행합니다","es":"La herramienta de revisión de cambios permite a los desarrolladores revisar PR en el repositorio de Razorpay. Revisa el diff, el estado de CI y la URL de vista previa de Storybook.","fr":"L''outil de révision de modifications permet aux développeurs de vérifier les PR dans le référentiel Razorpay. Il vérifie le diff, le statut de CI et l''URL de l''aperçu Storybook.","de":"Das Änderungs-Überprüfungstool ermöglicht es Entwicklern, PR im Razorpay-Repository zu überprüfen. Es überprüft den Diff, den CI-Status und die Storybook-Vorschau-URL.","pt":"O agente de habilidade ''review-changes'' revisa PRs no repositório Razorpay/Blade, verificando o diff, o status do CI e a URL de visualização do Storybook.","ru":"Агент навыков ''review-changes'' проверяет PR в репозитории Razorpay/Blade, проверяя diff, статус CI и URL-превью Storybook.","ar":"وكيل المهارات ''review-changes'' يراجع طلبات السحب في مستودع Razorpay/Blade، ويتحقق من الفرق والوضع المحدد والرابط المعاينة للstorybook.","en":"Design System that powers Razorpay"},"seo":{"title":{"zh":"Review Changes 技术 - Razorpay 设计系统","ja":"変更レビュー技術 - Razorpay デザインシステム","ko":"변경 리뷰 기술 - Razorpay 디자인 시스템","es":"Revisar cambios en Razorpay","fr":"Vérifier les modifications Razorpay","de":"Änderungen in Razorpay überprüfen","pt":"Revisão de Alteraç